-- Preguntas frecuentes de tres fichas de Teclab con consultas genéricas en
-- posición 7 a 11 sin clics (Search Console, 22/10-18/11/2026): Redes
-- Informáticas, Relaciones Laborales y Logística. Las respuestas salen del FAQ
-- oficial de cada ficha en teclab.edu.ar (22/11/2026); se dejó afuera «becas
-- o promociones». Reemplaza la columna slides entera: las preguntas que ya
-- estaban se conservan primero y en el mismo orden.
-- Aplicar con: npm run db:d1 -- --escribir --archivo sql/2026-11-22-faq-teclab-redes-rrll-logistica.sql

UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Redes Informáticas?","respuesta":"Estudiás fundamentos e interconexión de redes, servidores, servicios de red, scripting y automatización. La formación también incluye seguridad y gestión de redes para administrar la conectividad de una organización."},{"pregunta":"¿Qué hace un técnico en Redes Informáticas?","respuesta":"Configura y administra redes de datos, servidores y servicios de conectividad. Puede trabajar con direccionamiento IP, switching y routing, además de automatizar tareas de gestión de la infraestructura informática."},{"pregunta":"¿Cuál es la diferencia entre Redes Informáticas y Seguridad Informática?","respuesta":"Redes Informáticas se centra en la conectividad y la administración de redes y servidores. Seguridad Informática profundiza la protección de sistemas y datos, el análisis de riesgos y la respuesta ante amenazas. Las dos carreras comparten contenidos de redes."},{"pregunta":"¿Necesito conocimientos previos o saber programar para estudiar Redes Informáticas?","respuesta":"No. La carrera está pensada para comenzar desde cero y avanzar progresivamente en redes, lógica de programación, scripting y seguridad informática."},{"pregunta":"¿Cuál es la diferencia entre Redes Informáticas y soporte IT?","respuesta":"El soporte IT se enfoca en resolver problemas de equipos y sistemas, mientras que Redes Informáticas se centra en la conectividad y la infraestructura que permite que los dispositivos y servicios se comuniquen. Los dos campos pueden complementarse dentro de un equipo tecnológico."},{"pregunta":"¿Tiene salida laboral la Tecnicatura en Redes Informáticas?","respuesta":"Sí. Podés desarrollarte en soporte IT, administración de redes e infraestructura tecnológica, en compañías de tecnología, organizaciones con áreas de IT, centros de datos y proveedores de servicios informáticos que necesitan mantener sus sistemas conectados y funcionando."},{"pregunta":"¿Tiene certificado intermedio?","respuesta":"Sí. La carrera contempla el certificado intermedio de Asistente en Redes Informáticas, que acredita una etapa de la formación antes de completar el título final."},{"pregunta":"¿Qué título obtengo al finalizar?","respuesta":"El título oficial de Técnico Superior en Redes Informáticas, con validez nacional. La tecnicatura dura 2 años y se cursa 100% online."}]}]', updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE id = 220;
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Relaciones Laborales?","respuesta":"Estudiás relaciones individuales y colectivas del trabajo, remuneraciones, indemnizaciones, selección de personal y compensaciones. La formación combina normativa laboral y gestión de personas para acompañar los vínculos dentro de una organización."},{"pregunta":"¿Relaciones Laborales incluye liquidación de sueldos?","respuesta":"Sí. La formación aborda remuneraciones e indemnizaciones y la gestión de haberes, aportes y licencias. También incluye beneficios y compensaciones, vinculados con la administración de personal."},{"pregunta":"¿Cuál es la salida laboral de Relaciones Laborales?","respuesta":"La formación se relaciona con áreas de recursos humanos, administración de personal, liquidaciones, reclutamiento y selección. Puede aplicarse en empresas, consultoras y organizaciones que gestionan equipos y relaciones de trabajo."},{"pregunta":"¿Cuál es la diferencia entre Relaciones Laborales y Recursos Humanos?","respuesta":"Relaciones Laborales pone el foco en los vínculos laborales, la normativa, las remuneraciones y las relaciones individuales y colectivas del trabajo. Recursos Humanos suele tener una mirada más amplia sobre la gestión de las personas y la organización. Las dos áreas se conectan en selección, desarrollo, beneficios, clima y experiencia de las personas."},{"pregunta":"¿Dónde puede trabajar un Técnico Superior en Relaciones Laborales?","respuesta":"En áreas de Recursos Humanos y Relaciones Laborales de empresas de cualquier rubro, consultoras de selección y capacitación, organismos vinculados al empleo y la regulación laboral, sindicatos, o de manera independiente en consultoría."},{"pregunta":"¿Tiene certificado intermedio?","respuesta":"Sí. Al finalizar el primer año podés obtener el certificado intermedio de Auxiliar de Relaciones Laborales."},{"pregunta":"¿Necesito conocimientos previos para inscribirme?","respuesta":"No. La carrera está pensada para comenzar desde cero y avanzar progresivamente en relaciones laborales, derecho y gestión."},{"pregunta":"¿Qué título obtengo al finalizar?","respuesta":"El título oficial de Técnico Superior en Relaciones Laborales, con acreditación nacional. La tecnicatura dura 2 años y se cursa 100% online."}]}]', updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE id = 230;
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Logística?","respuesta":"Estudiás las bases operativas de la logística, la manipulación y distribución de envíos, el régimen courier, los procedimientos aduaneros y el despacho de mercadería, junto con gestión del transporte, gestión de proyectos, negociación y gestión de personas."},{"pregunta":"¿Qué hace un técnico en Logística?","respuesta":"Integra transporte, almacenamiento y distribución, registra movimientos y optimiza niveles de stock, articula proveedores, transportistas y clientes y analiza costos, tiempos y riesgos en la cadena de suministro."},{"pregunta":"¿Cuál es la salida laboral de Logística?","respuesta":"Transporte y distribución, en planificación de rutas, flotas y movimientos de carga; industria y comercio, en abastecimiento, almacenamiento y distribución de bienes; comercio electrónico, en gestión de pedidos y entregas de última milla, y comercio exterior y consultoría, en documentación y mejora de procesos logísticos."},{"pregunta":"¿Tiene certificado intermedio?","respuesta":"Sí. Al completar el primer año obtenés el certificado de Asistente en Logística, y al egresar, el título de Técnico Superior en Logística."},{"pregunta":"¿Tiene prácticas?","respuesta":"Sí. La Práctica Profesionalizante se cursa en el bimestre 8: son 340 horas reloj, 40 virtuales y 300 en una organización. Para hacerla se necesitan al menos 8 materias aprobadas, según las correlatividades del plan."},{"pregunta":"¿La Tecnicatura en Logística incluye comercio exterior?","respuesta":"Sí. Vas a trabajar contenidos de importaciones y exportaciones, Incoterms, documentación comercial, regímenes aduaneros, operatoria courier y despacho de mercadería."},{"pregunta":"¿Voy a aprender cómo se gestionan los pedidos de las tiendas online?","respuesta":"Sí. La carrera incorpora contenidos de distribución de envíos, tracking, comercio electrónico internacional, servicios courier y última milla."},{"pregunta":"¿Qué título obtengo al finalizar?","respuesta":"El título oficial de Técnico Superior en Logística, con acreditación nacional. La carrera dura 2 años y se cursa online."}]}]', updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE id = 243;
